import subprocess
import os

os.chdir(os.path.expanduser('~/.hermes'))

# Check if there are tools outside tools/ directory
result = subprocess.run(
    ['git', 'ls-tree', '-r', '--name-only', 'origin/main-pre-filter-2026-05-17'],
    capture_output=True, text=True
)

# Look for python files that might be tools but not in tools/
tool_like = []
for line in result.stdout.strip().split('\n'):
    if line.endswith('.py') and not line.startswith('tests/'):
        if any(x in line.lower() for x in ['tool', 'mcp', 'skill', 'agent', 'provider']):
            if not line.startswith('tools/'):
                tool_like.append(line)

print(f"Potential tools outside tools/: {len(tool_like)}")
for t in sorted(tool_like)[:30]:
    print(f"  {t}")
